# owner: platform
import unittest

from rosterkit.seating import seating_chart
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student(last + first, last, first, "A")


PEOPLE = [
    make("Halloway", "Juno"),
    make("Dunmere", "Piet"),
    make("Adler", "Zoe"),
]


class SeatingTests(unittest.TestCase):
    def test_sorted_by_last_name_into_rows(self):
        self.assertEqual(
            seating_chart(PEOPLE, 2),
            [
                "Row 1: Adler, Zoe | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row_when_seats_exceed_students(self):
        chart = seating_chart(PEOPLE, 10)
        self.assertEqual(len(chart), 1)

    def test_first_name_breaks_ties(self):
        people = [make("Poe", "Zed"), make("poe", "Amy")]
        chart = seating_chart(people, 2)
        self.assertEqual(chart, ["Row 1: poe, Amy | Poe, Zed"])

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_chart(PEOPLE, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_chart(PEOPLE, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_chart([], 4)

    def test_input_list_is_not_modified(self):
        original = list(PEOPLE)
        seating_chart(PEOPLE, 2)
        self.assertEqual(PEOPLE, original)
